<style>#al-branding-loader{position:fixed;inset:0;z-index:99999;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;background:var(--lb-bg);color:var(--lb-text);transition:opacity var(--lb-fade,250ms) ease,visibility var(--lb-fade,250ms) ease;{{ $loaderSetting->backdrop_blur?'backdrop-filter:blur(10px);':'' }}}#al-branding-loader.lb-hidden{opacity:0;visibility:hidden;pointer-events:none}.lb-spin{width:44px;height:44px;border:3px solid #ffffff55;border-top-color:var(--lb-accent);border-radius:50%;animation:lb-spin .8s linear infinite}.lb-track{width:220px;height:3px;background:#ffffff44;overflow:hidden}.lb-track i{display:block;width:40%;height:100%;background:var(--lb-accent);animation:lb-sweep 1.2s ease-in-out infinite}@keyframes lb-spin{to{transform:rotate(360deg)}}@keyframes lb-sweep{to{transform:translateX(260%)}}@media(prefers-reduced-motion:reduce){.lb-spin,.lb-track i{animation:none}}</style>
<script>(function(){const o=document.getElementById('al-branding-loader');if(!o)return;const m=o.dataset.trigger,k='al-loader-seen';try{if(m==='first-visit-session'&&sessionStorage.getItem(k)){o.remove();return}if(m==='first-visit-daily'&&localStorage.getItem(k)===new Date().toDateString()){o.remove();return}}catch(e){}const s=Date.now(),h=()=>setTimeout(()=>{o.classList.add('lb-hidden');setTimeout(()=>o.remove(),Number(o.dataset.fade||250))},Math.max(0,Number(o.dataset.min||0)-(Date.now()-s)));addEventListener('load',h,{once:true});setTimeout(h,Math.max(1500,Number(o.dataset.min||500)+4000));try{if(m==='first-visit-session')sessionStorage.setItem(k,'1');if(m==='first-visit-daily')localStorage.setItem(k,new Date().toDateString())}catch(e){}document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||a.target||a.hasAttribute('download'))return;const u=new URL(a.href,location.href);if(u.origin!==location.origin||u.pathname===location.pathname||/^\/(admin|api|payment|payments|checkout|webhook|webhooks|live-class|live-classes)(\/|$)/.test(u.pathname))return;o.classList.remove('lb-hidden')},true)})();</script>
